<template>
  <AppLoader v-if="isLoading" subject="profile" />
  <template v-else>
    <AppError v-if="error" title="Failed to load profile" :error="error" :action="refetch" action-text="Retry" />
    <AppEmpty v-else-if="!sharedProfile" subject="profile" />
    <Card v-else class="w-full mx-auto">
      <CardContent class="pt-6">
        <ProfileBioDisplay
          :bio="sharedProfile.bio"
          :profile-picture-url="sharedProfile.profile_picture_url"
          :profile-picture-original-url="sharedProfile.profile_picture_original_url"
          :full-name="fullName"
          :city="sharedProfile.city"
          :state="sharedProfile.state"
          :joined-at="sharedProfile.created_at"
          empty-message="This user has not provided profile information yet"
        />
      </CardContent>
    </Card>
  </template>
</template>

<script setup lang="ts">
import { getSharedDetails } from '~/client';

definePageMeta({
  layout: 'share',
  auth: false,
});

const route = useRoute('share-profile-code');
const code = computed(() => route.params.code);

const {
  data: sharedProfile,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['share.profile.code', code.value],
  query: () => getSharedDetails({ composable: '$fetch', path: { shareable_code: code.value } }),
  enabled: () => !!code.value,
});

const fullName = computed(() =>
  sharedProfile.value && !error.value
    ? `${sharedProfile.value.first_name} ${sharedProfile.value.last_name}`.trim()
    : 'Profile'
);

useHead({
  title: fullName,
});

// Can't throw a 404 from the query, so handle it here (same pattern as share/project/[hash].vue).
watch(
  () => error.value,
  (newError) => {
    if (newError && newError.statusCode === 404) {
      throw createError({
        statusCode: 404,
        statusMessage: newError?.data?.detail || 'Profile not found',
        fatal: true,
      });
    }
  }
);
</script>
